body:
Wonderful project. Thanks! I am an nginx noob spoiled by SWAG and ready-made LSIO confs and having trouble getting reverse proxy to function with surmai. The config below is giving me a 502 error. Any recommendations?

```
server {
    listen 443 ssl;
    listen [::]:443 ssl;

    server_name surmai.*;

    include /config/nginx/ssl.conf;

    client_max_body_size 0;

    location / {

        include /config/nginx/proxy.conf;
        include /config/nginx/resolver.conf;
        set $upstream_app surmai;
        set $upstream_port 8080;
        set $upstream_proto http;
        proxy_pass $upstream_proto://$upstream_app:$upstream_port;

    }
}
```
